/* ==========================================================================
  Take picture styles
========================================================================== */
.take-picture-wrapper {
  height: 100%;
  width: 100%;
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column-reverse;
  justify-content: space-between;
  /* Should be higher than the the video. */
  z-index: 111;
}

.take-picture-video-element {
  position: absolute;
  /* Should be higher than the z-index of '.layout-atlas .region-sidebar' so it sits on top of the page. */
  z-index: 110;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  object-fit: cover;
  width: 100%;
  height: 100%;
  background-color: black;
}

.take-picture-action-control-wrapper {
  display: flex;
  justify-content: center;
  flex-direction: row;
  align-items: center;
  /* should be higher than the video. */
  z-index: 111;
  margin-bottom: 74px;
}

.take-picture-action-switch-control-wrapper {
  display: flex;
  justify-content: space-between;
  flex-direction: row;
  align-items: center;
  /* should be higher than the video. */
  z-index: 111;
  margin-bottom: 74px;
}

.take-picture-close-control-wrapper {
  display: flex;
  justify-content: flex-start;
  flex-direction: column;
  align-items: flex-start;
  /* should be higher than the video. */
  z-index: 111;
