input[type=checkbox].three-state-checkbox {
  position: relative !important;
  width: 16px;
  height: 16px;
  margin: 0 !important;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
  appearance: none;
  -moz-appearance: none;
  -webkit-appearance: none;
