  position: absolute;
  display: block;
  transition: all 0.3s ease;
}
input[type=checkbox].three-state-checkbox:before {
  width: 100%;
  height: 100%;
  content: "";
  border: 1px solid #e7e7e9;
  border-radius: 4px;
  background-color: transparent;
}
