/* LOADER */
.mx-progress.mx-progress-empty {
  width: 100%;
  max-width: 100%;
  top: 0;
  margin: 0;
  padding: 0;
}

.mx-progress.mx-progress-empty .mx-progress-message {
  background-color: #e6e6e6;
  margin-bottom: 0px;
}

.mx-progress.mx-progress-empty .mx-progress-message {
  height: 4px;
}

.mx-progress.mx-progress-empty .mx-progress-indicator:before,
.mx-progress.mx-progress-empty .mx-progress-indicator:after {
  background-color: initial;
  width: 10%;
  background-image: linear-gradient(90deg, #2387aa 0, #2387aa 0);
  animation: loading 2s cubic-bezier(0.1, 0.85, 0.9, 0.15) infinite, loading-opacity 2s ease-in-out infinite alternate;
  transform: initial;
  background-repeat: no-repeat;
  z-index: 99999;
}

@keyframes loading-opacity {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 1;
  }
}
@keyframes loading {
  0% {
    left: 0;
  }
  to {
    left: 100%;
  }
}
.hidden-element {
  visibility: hidden;
  height: 0px;
}

