.s-event-wrap {
  position: absolute;
  overflow: visible;
  min-width: 6px;
  min-height: 6px;
  z-index: 7;
  align-items: center;
  pointer-events: all;
  transition: background-color 0.2s, color 0.2s, opacity 0.2s, font-weight 0.2s, border 0.2s;
  contain: layout paint;
}
.s-event-wrap.b-event-planned {
  --event-background-color: var(--event-background-color-planned);
}
.s-event-wrap.b-event-actual {
  --event-background-color: var(--event-background-color-actual);
}
