  cursor: default;
}

.s-event {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  height: 100%;
  grid-area: body;
  color: var(--event-color);
  background-color: var(--event-background-color);
  border-color: var(--event-border-color);
  border-width: var(--event-border-width);
  border-style: var(--event-border-style);
  border-radius: var(--event-border-radius);
  font-weight: var(--event-font-weight);
  opacity: var(--event-opacity);
  user-select: none;
  cursor: pointer;
  overflow: hidden;
  overflow: clip;
  white-space: nowrap;
  width: calc(100% - 1px);
  text-align: left;
  min-width: 5px;
  min-height: 5px;
  transition: background-color 0.2s, color 0.2s, opacity 0.2s, font-weight 0.2s, border 0.2s;
  position: relative;
}

.s-event-content {
  position: sticky;
  left: 9.75px;
  margin: 0 6.5px 0 9.75px;
  text-overflow: ellipsis;
  overflow: hidden;
  overflow: clip;
  display: flex;
  min-width: 0;
  font-size: 13px;
  z-index: 1;
}

.s-resize-handle {
  position: absolute;
  height: 50%;
  width: 12px;
  padding: 0 2px;
  top: 25%;
}
.s-resize-handle:before {
  content: "";
  position: relative;
  display: block;
  top: 0;
  width: 8px;
  height: 100%;
  opacity: 0.7;
  background-size: 2px;
  background: linear-gradient(to right, #fff 1px, transparent 1px) 3px;
  cursor: col-resize;
  z-index: 1;
}
.s-resize-handle.s-left-resize {
  left: -1px;
}
.s-resize-handle.s-right-resize {
  right: -1px;
  left: auto;
}

.s-grid {
