  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: var(--bg);
}

.s-body-container {
  position: relative;
  flex: 1 1 0;
  contain: strict;
  overflow-x: hidden;
  overflow-y: auto;
  max-height: 100%;
  -webkit-overflow-scrolling: touch;
  overflow-anchor: none;
  box-sizing: border-box;
}

.s-grid-subgrid {
  display: inline-flex;
  position: relative;
  overscroll-behavior: none auto;
  overflow-y: hidden;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  overflow-anchor: none;
