.siemens-gantt {
  --color: #444444;
  --color-header: var(--color);
  --bg: #fff;
  --bg-panel: #E7E7E7;
  --grid-border-color: #bdbdbd;
  --grid-row-border-color: #e0e0e0;
  --grid-column-border-color: #e0e0e0;
  --grid-splitter-bg: #d6d6d6;
  --grid-bg-odd: rgba(0, 0, 0, 0.03);
  --grid-bg-hover: rgba(255, 178, 32, 0.1);
  --grid-bg-selected: rgba(255, 178, 32, 0.16);
  --grid-bg-hover-selected: rgba(255, 178, 32, 0.20);
  --grid-bg-timeaxis-selected: rgba(255, 178, 32, 0.07);
  --event-background-color-planned: #3E95B8;
  --event-background-color-actual: #72ae56;
  --event-border: #fff;
  --event-border-radius: 0;
  --event-color: #fff;
  --event-hover-color: #fff;
  --event-opacity: 1;
  --event-hover-opacity: 1;
  --event-font-weight: 500;
  --chip-border-color: #186686;
}

